<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();$q=$db->prepare('SELECT currency,amount,reason,reference_type,reference_id,created_at FROM currency_transactions WHERE user_id=? ORDER BY id DESC LIMIT 100');$q->execute([$currentUser['id']]);$rows=$q->fetchAll();page_start('Currency History');?><section class="Panel"><h1>Currency History</h1><p>Balance: <?=(int)$currentUser['tickets']?> Tickets · <?=(int)$currentUser['robux']?> Robux</p><table class="Grid"><tr><th>Currency</th><th>Change</th><th>Reason</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e(ucfirst($r['currency']))?></td><td><?=((int)$r['amount']>0?'+':'').(int)$r['amount']?></td><td><?=e($r['reason'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">No transactions yet.</td></tr><?php endif;?></table></section><?php page_end();?>